import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import './Auth.css';

export default function Login({ onLogin }) {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [msg, setMsg] = useState('');
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setMsg('');

    // Préparer les données en form-urlencoded pour FastAPI OAuth2
    const formData = new URLSearchParams();
    formData.append('username', email);
    formData.append('password', password);

    try {
      const res = await fetch('http://localhost:8000/token', {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: formData.toString(),
      });

      if (res.ok) {
        const data = await res.json();
        // data.access_token contient le JWT
        onLogin(data.access_token);
        navigate('/landing');
      } else {
        const error = await res.json();
        setMsg(error.detail || 'Échec de la connexion');
      }
    } catch (err) {
      setMsg('Impossible de joindre le serveur');
    }
  };

  return (
    <div className="auth-wrapper">
      <div className="dark-overlay"></div>
      <div className="auth-card">
        <h2>Se connecter</h2>
        <form className="auth-form" onSubmit={handleSubmit}>
          <input
            type="email"
            placeholder="Email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
          />
          <input
            type="password"
            placeholder="Mot de passe"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
          />
          <button className="auth-button" type="submit">Connexion</button>
        </form>
        {msg && <p style={{ color: 'red', marginTop: '1rem' }}>{msg}</p>}
        <div className="auth-footer">
          Pas encore de compte ? <Link to="/signup">Créer un compte</Link>
        </div>
      </div>
    </div>
  );
}
